const FX_KEY='moze-fx-v1',FX_TTL=12*3600e3,FX_RETRY=10*60e3;
const FX_URLS=['https://open.er-api.com/v6/latest/TWD','https://cdn.jsdelivr.net/npm/@fawazahmed0/currency-api@latest/v1/currencies/twd.json'];
