function renderMetrics(){const key=monthKey(),cur=monthStats(key),prev=monthStats(addMonths(key,-1)),[nwPrev,nwCur]=netWorthAt([addMonths(key,-1),key]),out=cur.out,inc=cur.inc,nw=netWorth(state.accounts);mBalance.textContent=money(nwCur);mExpense.textContent=money(out);mIncome.textContent=money(inc);{const conv=nw.conv.reduce((m,[c,v,t])=>{m[c]=m[c]||[0,0];m[c][0]+=v;m[c][1]+=t;return m},{}),parts=[];for(const [c,[v,t]] of Object.entries(conv))parts.push(`${acctMoney(v,{currency:c})} ≈ ${money(t)}`);const miss=Object.entries(nw.missing).map(([c,v])=>acctMoney(v,{currency:c}));if(parts.length||miss.length)refreshFx();const fxNote=[parts.length?`含外幣 ${parts.join(' · ')}（匯率 ${fxDateLabel()}）`:'',miss.length?`未計入（尚無匯率）：${miss.join(' · ')}`:''].filter(Boolean).join('；');mBalanceDelta.textContent=deltaText(nwCur,nwPrev)+(fxNote?' · 含外幣換算':'');mBalanceDelta.title=fxNote;setDeltaClass(mBalanceDelta,nwCur-nwPrev);}mExpenseDelta.textContent=deltaText(out,prev.out);setDeltaClass(mExpenseDelta,out-prev.out,true);mIncomeDelta.textContent=deltaText(inc,prev.inc);setDeltaClass(mIncomeDelta,inc-prev.inc)}
function setDeltaClass(el,d,inverse){if(!el?.classList)return;el.classList.remove('delta-up','delta-down');if(d)el.classList.add((d>0)!==!!inverse?'delta-up':'delta-down')}
function renderChart(){const n=Number(document.getElementById('chartRange')?.value||12)||12;mountChart(cashflowChart,chartSeries(n),{bars:true,line:true});if(trendChart)mountChart(trendChart,chartSeries(12),{bars:false,line:true})}
function txRow(t){let c=cat(t.category);return `<div class="row"><div class="row-left"><div class="mini-icon">${esc(c.icon)}</div><div><b>${esc(t.name)}</b><div class="hint">${esc(t.merchant||'')} · ${esc(acct(t.account).name)}</div></div></div><div class="amount" style="color:${t.kind==='expense'?'var(--accent)':t.kind==='income'?'var(--green)':''}">${t.kind==='expense'?'−':t.kind==='income'?'+':''}${money(t.amount)}</div></div>`}
function renderRecent(){recent.innerHTML=state.transactions.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6).map(txRow).join('')||'<div class="empty">尚無交易</div>';renderPending();renderLoanTracking()}
// V26.3 overview: credit card bills and loan tracking by person.
function avatarHtml(o){const n=String((o&&typeof o==='object'?o.name:o)||'?');let h=0;for(const ch of n)h=(h*31+ch.codePointAt(0))%360;return `<span class="avatar" style="--h:${h}">${esc([...n.trim()][0]||'?')}</span>`}
function mdLabel(date){const [,m,d]=String(date).split('-').map(Number);return `${m}/${d}`}
function cardBill(a,base=new Date()){const p=cardPeriod(a,base,0),bill=state.transactions.filter(t=>String(t.account)===String(a.id)&&t.kind==='expense'&&!isUnappliedPending(t)&&t.date>=p.start&&t.date<=p.end&&!t.cardPayment).reduce((s,t)=>s+Math.abs(Number(t.amount||0)),0),paid=creditStatementPayments(a,p).reduce((s,t)=>s+Math.abs(Number(t.amount||0)),0),status=creditStatementStatus(a,p,paid,bill);return {card:a,period:p,bill:Math.round(bill),paid:Math.round(paid),due:Math.max(0,Math.round(bill-paid)),status}}
function cardBills(base=new Date()){const order={overdue:0,unpaid:1,partial:1,paid:2};return state.accounts.filter(a=>a.type==='card').map(a=>cardBill(a,base)).sort((x,y)=>(order[x.status.key]-order[y.status.key])||x.status.date.localeCompare(y.status.date))}
function loanGroups(){const map=new Map();for(const l of (state.loans||[])){if(loanStatus(l)!=='active')continue;const p=l.person||'未指定對象';if(!map.has(p))map.set(p,{person:p,receivable:0,payable:0,net:0,latest:'',firstId:l.id});const g=map.get(p),dir=loanDirection(l),out=loanOutstanding(l);g[dir]+=1;g.net+=(dir==='receivable'?1:-1)*out;const last=[l.date,...(l.payments||[]).map(x=>x.date)].filter(Boolean).sort().pop()||'';if(last>g.latest)g.latest=last}return [...map.values()].sort((a,b)=>Math.abs(b.net)-Math.abs(a.net))}
function renderLoanTracking(){const el=document.getElementById('loanSummary');if(!el)return;const gs=loanGroups(),head=document.getElementById('loanTrackTotal');if(head)head.textContent=gs.length?`${gs.length} 位對象`:'';el.innerHTML=gs.length?gs.slice(0,5).map(g=>{const kind=g.receivable&&g.payable?'mixed':g.payable?'payable':'receivable',desc=[g.receivable?`${g.receivable} 筆應收款項`:'',g.payable?`${g.payable} 筆應付款項`:''].filter(Boolean).join(' · ');return `<button type="button" class="loan-track ${kind}" data-loan-id="${esc(g.firstId)}"><div><b>${esc(g.person)}</b><small>${desc}</small></div><div class="day-side"><b class="${g.net>=0?'income-text':'expense-text'}">${g.net>=0?'+':'−'}${money(Math.abs(g.net))}</b><small>${esc(g.latest||'')}</small></div></button>`}).join('')+(gs.length>5?`<button type="button" class="ghost more-link" data-view="loans">查看更多（另 ${gs.length-5} 位）</button>`:''):'<div class="empty">目前沒有進行中的借還款</div>'}
function renderCards(){{const bills=cardBills(),head=document.getElementById('creditTotal'),total=bills.reduce((x,b)=>x+b.due,0);if(head)head.textContent=bills.length?`${bills.length} 張 · 未繳合計 ${money(total)}`:'';creditCards.innerHTML=bills.map(b=>{const a=b.card,st=b.status,over=st.key==='overdue',dueTxt=st.key==='paid'?`${mdLabel(st.date)} 到期 · 已繳清`:over?`已於 ${mdLabel(st.date)} 到期`:`將於 ${mdLabel(st.date)} 到期`;return `<button type="button" class="card-bill ${st.key}" data-dashboard-credit="${esc(a.id)}">${avatarHtml(a)}<div class="day-main"><small class="card-status ${st.key}">${st.label}</small><b>${acctName(a)}</b></div><div class="day-side"><small class="${over?'overdue':''}">${dueTxt}</small><b class="${b.due?'expense-text':''}">${money(b.due)}</b></div></button>`}).join('')||'<div class="empty">尚無信用卡</div>';}document.querySelectorAll('[data-dashboard-credit]').forEach(b=>b.onclick=()=>{nav('accounts');openCreditAccount(b.dataset.dashboardCredit)});renderUpcoming()}
// V26.1: tags / time helpers and calendar day totals.
function parseTags(v){const out=[];for(const raw of String(v??'').split(/[\s,，、]+/)){const t=raw.replace(/^#+/,'').trim().slice(0,20);if(t&&!out.includes(t))out.push(t)}return out.slice(0,10)}
function nowTime(){const d=new Date();return `${pad2(d.getHours())}:${pad2(d.getMinutes())}`}
function txSigned(t){const v=Math.abs(Number(t.amount||0)),tw=txTWD(v,t.account)??v;return t.kind==='expense'?-tw:t.kind==='income'?tw:0}
function dayTotals(date){let out=0,inc=0;for(const t of state.transactions){if(t.date!==date||isUnappliedPending(t))continue;const v=txSigned(t);if(v<0)out-=v;else inc+=v}return {out:Math.round(out),inc:Math.round(inc),net:Math.round(inc-out)}}
function monthProjectTotal(key){const pb=typeof periodBounds==='function'?periodBounds(key):{start:key+'-01',end:monthEnd(key)};let s=0;for(const t of state.transactions)if(t.project&&t.date&&t.date>=pb.start&&t.date<=pb.end&&t.kind==='expense')s+=Math.abs(txSigned(t));return Math.round(s)}
function txExtra(t){const bits=[];if(t.time)bits.push(esc(t.time));if(Array.isArray(t.tags)&&t.tags.length)bits.push(t.tags.map(x=>'#'+esc(x)).join(' '));return bits.length?' · '+bits.join(' · '):''}
function tagsHtml(t){return Array.isArray(t?.tags)?t.tags.map(x=>'#'+esc(x)).join(' '):''}
const WEEKDAYS=['週日','週一','週二','週三','週四','週五','週六'];
function renderCalendar(){const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth();const first=calendarLead(y,m),days=new Date(y,m+1,0).getDate(),today=isoDate(new Date());let html='';for(let i=0;i<first;i++)html+='<div></div>';for(let n=1;n<=days;n++){const date=`${y}-${String(m+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`,has=state.transactions.some(t=>t.date===date),dt=has?dayTotals(date):null,wd=new Date(y,m,n).getDay();html+=`<button type="button" class="day ${date===selectedDate?'sel':''} ${date===today?'today':''} ${wd===0||wd===6?'wkend':''}" data-date="${date}"><span class="day-num">${n}</span>${dt&&dt.net?`<small class="day-amt ${dt.net<0?'neg':'pos'}">${dt.net<0?'−':'+'}${compactNum(Math.abs(dt.net))}</small>`:has?'<i class="dot"></i>':''}</button>`}calendarGrid.innerHTML=html;calendarGrid.querySelectorAll('.day').forEach(b=>b.onclick=()=>{selectedDate=b.dataset.date;renderCalendar();renderDaily()});monthTitle.textContent=`${y} 年 ${m+1} 月`;periodLabel.textContent=`${y}/${String(m+1).padStart(2,'0')}`}
function renderDaily(){const ts=state.transactions.filter(t=>t.date===selectedDate).sort((a,b)=>String(b.time||'').localeCompare(String(a.time||''))),key=selectedDate.slice(0,7),ms=monthStats(key),pt=monthProjectTotal(key),dt=dayTotals(selectedDate),[yy,mm,dd]=selectedDate.split('-').map(Number),wd=WEEKDAYS[new Date(yy,mm-1,dd).getDay()];const box=document.getElementById('monthStats');if(box)box.innerHTML=`<div><b>${mm} 月統計</b>${pt?`<small>專案總額 ${money(pt)}</small>`:''}</div><div class="month-stats-amt"><span class="expense-text">${money(ms.out)}</span> · <span class="income-text">${money(ms.inc)}</span></div>`;dailyCaption.textContent=`${yy}/${pad2(mm)}/${pad2(dd)}（${wd}）${ts.length?` · 支出 ${money(dt.out)} · 收入 ${money(dt.inc)}`:''}`;dailyList.innerHTML=ts.length?ts.map(t=>{const v=txSigned(t),proj=t.project?state.projects.find(p=>String(p.id)===String(t.project)):null,sub=[t.merchant||t.person||'',t.time||'',(Array.isArray(t.tags)?t.tags.map(x=>'#'+x).join(' '):'')].filter(Boolean);return `<div class="day-row" data-txid="${esc(t.id)}"><div class="tx-icon">${esc(cat(t.category).icon)}</div><div class="day-main"><b>${esc(t.name)}${t.pending?' <span class="chip pending">待完成</span>':''}</b><small>${esc(sub.join(' · ')||txTypeLabel(t))}</small></div><div class="day-side"><b class="${v<0?'expense-text':v>0?'income-text':''}">${v>0?'+':v<0?'−':''}${money(Math.abs(v||Number(t.amount||0)))}</b><span class="chips">${proj?`<i>${esc(proj.name)}</i>`:''}<i>${acctName(acct(t.account))}</i></span></div></div>`}).join(''):'<div class="empty">當日沒有交易</div>';dailyList.querySelectorAll('.day-row').forEach(r=>r.onclick=()=>openDetail(r.dataset.txid))}
function renderTransactions(){let q=(txSearch.value||'').toLowerCase(),type=txType.value,ca=txCategory.value,ac=txAccount.value;let ts=state.transactions.filter(t=>(!q||`${esc(t.name)} ${esc(t.merchant||'')} ${esc(t.note||'')}`.toLowerCase().includes(q))&&(type==='all'||t.kind===type)&&(ca==='all'||t.category===ca)&&(ac==='all'||t.account===ac)).sort((a,b)=>b.date.localeCompare(a.date));let count=ts.length,out=ts.filter(t=>t.kind==='expense').reduce((s,t)=>s+t.amount,0),inc=ts.filter(t=>t.kind==='income').reduce((s,t)=>s+t.amount,0);let summary=`<div class="tx-toolbar"><div class="tx-summary"><span>共 <b>${count}</b> 筆</span><span>支出 <b class="expense-text">${money(out)}</b></span><span>收入 <b class="income-text">${money(inc)}</b></span></div></div>`;let groups={};ts.forEach(t=>(groups[t.date]??=[]).push(t));let body=Object.entries(groups).map(([date,list])=>{let dayOut=list.filter(t=>t.kind==='expense').reduce((s,t)=>s+t.amount,0),dayIn=list.filter(t=>t.kind==='income').reduce((s,t)=>s+t.amount,0);return `<div class="tx-group"><div class="tx-group-head"><b>${date}</b><span>${dayOut?'支出 '+money(dayOut):''}${dayIn?' · 收入 '+money(dayIn):''}</span></div>${list.map(t=>{let c=cat(t.category),amount=t.kind==='expense'?'−'+money(t.amount):t.kind==='income'?'+'+money(t.amount):money(t.amount);return `<div class="tx-entry" data-txid="${t.id}"><div class="tx-icon">${esc(c.icon)}</div><div><div class="tx-name">${esc(t.name)}</div><div class="tx-meta">${esc(t.merchant||'—')} · ${esc(acct(t.account).name)}${esc(t.project?' · '+(state.projects.find(p=>String(p.id)===String(t.project))?.name||''):'')}</div></div><div class="tx-type">${t.kind==='expense'?'支出':t.kind==='income'?'收入':'轉帳'}</div><div class="tx-actions"><b class="tx-amount ${t.kind==='expense'?'expense-text':t.kind==='income'?'income-text':''}">${amount}</b></div></div>`}).join('')}</div>`}).join('')||'<div class="panel empty">找不到符合條件的交易</div>';txTable.innerHTML=summary+`<div class="tx-groups">${body}</div>`;document.querySelectorAll('.tx-entry').forEach(row=>row.onclick=()=>openDetail(row.dataset.txid))}
function openDetail(id){let t=state.transactions.find(x=>String(x.id)===String(id));if(!t)return;window.detailId=t.id;let c=cat(t.category),project=t.project?(state.projects.find(p=>String(p.id)===String(t.project))?.name||'—'):'無專案';detailTitle.textContent=t.name;detailSubtitle.textContent=t.date;detailGrid.innerHTML=`<div class="detail-box"><small>金額</small><b class="${t.kind==='expense'?'expense-text':t.kind==='income'?'income-text':''}">${t.kind==='expense'?'−':t.kind==='income'?'+':''}${money(t.amount)}</b></div><div class="detail-box"><small>類型</small><b>${t.kind==='expense'?'支出':t.kind==='income'?'收入':'轉帳'}</b></div><div class="detail-box"><small>分類</small><b>${esc(c.icon)} ${esc(c.name)}</b></div><div class="detail-box"><small>帳戶</small><b>${esc(acct(t.account).name)}</b></div><div class="detail-box"><small>專案</small><b>${project}</b></div><div class="detail-box"><small>商家</small><b>${esc(t.merchant||'—')}</b></div><div class="detail-box detail-wide"><small>備註</small><b>${esc(t.note||'—')}</b></div>`;detailBg.classList.add('open')}
// V25.11: loan / loanPayment transactions are owned by the loans page; editing or deleting them
// from the transaction list would leave the loan record and account balance inconsistent.
function isLoanTx(t){return !!t&&(t.kind==='loan'||t.kind==='loanPayment'||!!t.loanRecord)}
function blockLoanTx(t){if(!isLoanTx(t))return false;alert('這是借還款交易，請到「借還款」頁面處理（收款／還款、停止追蹤）。\n直接在交易明細編輯或刪除，會造成借還款金額與帳戶餘額不一致。');return true}
async function deleteTx(id){let t=state.transactions.find(x=>String(x.id)===String(id));if(!t)return;if(blockLoanTx(t))return;if(t.installment){const ids=installmentDeleteChoice(t);if(!ids)return;for(const x of state.transactions.filter(x=>ids.includes(String(x.id))))adjust(x,-1);state.transactions=state.transactions.filter(x=>!ids.includes(String(x.id)));await save();detailBg.classList.remove('open');render();return}if(!confirm(`確定刪除「${t.name}」${money(t.amount)}？`))return;adjust(t,-1);state.transactions=state.transactions.filter(x=>String(x.id)!==String(id));await save();detailBg.classList.remove('open');render()}
function fillFilters(){let c=catOptionsHTML('',txCategory?.value,{all:true});txCategory.innerHTML=c;txAccount.innerHTML='<option value="all">全部帳戶</option>'+acctOrdered(state.accounts).map(x=>`<option value="${x.id}">${acctName(x)}</option>`).join('');formCategory.innerHTML=catOptionsHTML('',formCategory?.value);formAccount.innerHTML=acctActive(acctOrdered(state.accounts),formAccount.value).map(x=>`<option value="${x.id}">${acctName(x)}</option>`).join('');formToAccount.innerHTML=acctActive(acctOrdered(state.accounts),formToAccount.value).map(x=>`<option value="${x.id}">${acctName(x)}</option>`).join('');formProject.innerHTML='<option value="">無專案</option>'+state.projects.filter(x=>!x.archived||String(x.id)===String(formProject.value)).map(x=>`<option value="${x.id}">${esc(x.name)}${x.archived?'（已封存）':''}</option>`).join('')}
let selectedCreditCardId=null;
let selectedAccountId=null;
let creditStatementOffset=0;
let creditDetailTab='statement';
function pad2(n){return String(n).padStart(2,'0')}
function isoDate(d){return `${d.getFullYear()}-${pad2(d.getMonth()+1)}-${pad2(d.getDate())}`}
function cardStatementAnchor(card, base=new Date(), offset=0){
  const [y,m]=cardNominalMonth(card,base,offset);
  return cardStmtEnd(card,y,m);
}
function cardPeriod(card, base=new Date(), offset=creditStatementOffset){
  const [y,m]=cardNominalMonth(card,base,offset);
  const end=cardStmtEnd(card,y,m), prevEnd=cardStmtEnd(card,y,m-1);
  const start=new Date(prevEnd.getFullYear(),prevEnd.getMonth(),prevEnd.getDate()+1);
  return {start:isoDate(start),end:isoDate(end),offset};
}
function cardStatementDueDate(card, period){
  const dueDay=Math.min(31,Math.max(1,Number(card.due||5)));
  const end=new Date(period.end+'T00:00:00');
  const endDay=new Date(end.getFullYear(),end.getMonth()+1,0).getDate();
  const due=new Date(end.getFullYear(),end.getMonth(),Math.min(dueDay,endDay));
  if(due<=end) due.setMonth(due.getMonth()+1);
  return cardAdjustDate(card,due,card.dueWeekend);
}
function creditStatementKey(card, period){return `${card.id}|${period.start}|${period.end}`;}
function paymentBelongsToPeriod(payment, card, period){
  const key=creditStatementKey(card,period);
  if(payment.cardStatementKey) return payment.cardStatementKey===key;
  // V26.3: an unkeyed payment (e.g. imported from CSV) pays the statement that closed before it:
  // made after this statement's closing date and on or before the next closing date.
  const [y,m]=period.end.split('-').map(Number);let ne=cardStmtEnd(card,y,m);if(isoDate(ne)<=period.end)ne=cardStmtEnd(card,y,m+1);const nextEnd=isoDate(ne);
  return payment.date>period.end&&payment.date<=nextEnd;
}
function creditStatementPayments(card,period){
  return state.transactions.filter(t=>t.cardPayment&&String(t.toAccount)===String(card.id)&&paymentBelongsToPeriod(t,card,period)).sort((a,b)=>b.date.localeCompare(a.date));
}
function creditStatementStatus(card, period, paid, dueAmount){
  const dueDate=cardStatementDueDate(card,period), today=new Date(); today.setHours(0,0,0,0);
  if(dueAmount<=0) return {key:'paid',label:'已繳清',date:isoDate(dueDate)};
  if(paid>=dueAmount) return {key:'paid',label:'已繳清',date:isoDate(dueDate)};
  if(today>dueDate) return {key:'overdue',label:'已逾期',date:isoDate(dueDate)};
  if(paid>0) return {key:'partial',label:'部分繳款',date:isoDate(dueDate)};
  return {key:'unpaid',label:'待繳款',date:isoDate(dueDate)};
}
function accountHasTransactions(accountId){return state.transactions.some(t=>String(t.account)===String(accountId)||String(t.toAccount)===String(accountId))}
async function deleteAccount(accountId){
  const a=state.accounts.find(x=>String(x.id)===String(accountId)); if(!a)return;
  if(accountHasTransactions(accountId)){alert(`「${a.name}」仍有關聯交易，無法刪除。\n請先刪除或轉移與此帳戶相關的交易。`);return}
  if(Math.abs(Number(a.balance)||0)>0.000001){alert(`「${a.name}」目前餘額為 ${money(a.balance)}，請先將餘額歸零後再刪除。`);return}
  if(!confirm(`確定刪除帳戶「${a.name}」？`))return;
  state.accounts=state.accounts.filter(x=>String(x.id)!==String(accountId));
  if(String(selectedCreditCardId)===String(accountId))selectedCreditCardId=null;if(String(selectedAccountId)===String(accountId))selectedAccountId=null;
  await save();render();
}
function openAccountDetail(id){selectedAccountId=id;selectedCreditCardId=null;selectedBank=null;renderAccounts()}
function renderAccountDetail(){const el=document.getElementById('accountDetail'),a=selectedAccountId?acct(selectedAccountId):null;if(!el||!a||!a.id||a.type==='card'){if(el)el.hidden=true;return}const ts=state.transactions.filter(t=>String(t.account)===String(a.id)||String(t.toAccount)===String(a.id)).sort((x,y)=>y.date.localeCompare(x.date));const income=ts.filter(t=>t.kind==='income'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0);const expense=ts.filter(t=>t.kind==='expense'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0);const transferIn=ts.filter(t=>t.kind==='transfer'&&String(t.toAccount)===String(a.id)).reduce((s,t)=>s+t.amount,0);const transferOut=ts.filter(t=>t.kind==='transfer'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0);el.hidden=false;el.innerHTML=`<div class="account-detail-head"><div class="account-detail-title"><div class="account-detail-icon">${svgForAccount(a)}</div><div><h3>${acctName(a)}</h3><div class="hint">${acctTypeLabel(a)} · 帳戶明細</div></div></div><button type="button" class="secondary" data-close-account-detail>關閉</button></div><div class="account-detail-summary"><div class="account-summary-box"><span>目前餘額</span><b>${acctMoney(a.balance,a)}</b></div><div class="account-summary-box"><span>收入</span><b class="income-text">${money(income+transferIn)}</b></div><div class="account-summary-box"><span>支出</span><b class="expense-text">${money(expense+transferOut)}</b></div></div>${acctInfoHTML(a)}<div class="pane-tx"><div class="panel-head" style="margin:8px 0 10px"><h3 style="margin:0">相關交易</h3><span class="hint">${ts.length} 筆</span></div><div class="account-detail-list">${ts.length?ts.map(t=>{const c=cat(t.category);let sign=t.kind==='income'||(t.kind==='transfer'&&String(t.toAccount)===String(a.id))?'+':'−';let cls=sign==='+'?'income-text':'expense-text';return `<div class="account-detail-row"><span class="account-detail-date">${t.date}</span><div class="mini-icon">${esc(c.icon)}</div><div><b>${esc(t.name)}</b><div class="tx-meta">${esc(t.merchant||t.note||'—')}${t.kind==='transfer'?' · 轉帳':''}</div></div><div class="amount ${cls}">${sign}${money(t.amount)}</div></div>`}).join(''):'<div class="empty">目前沒有相關交易</div>'}</div></div>`;el.querySelector('[data-close-account-detail]')?.addEventListener('click',()=>{selectedAccountId=null;el.hidden=true;renderAccounts()})}
function renderAccounts(){
  const ordered=acctOrdered(state.accounts),cards=ordered.filter(a=>a.type==='card'), normal=ordered.filter(a=>a.type!=='card');
  const normalHtml=normal.map(a=>`<div class="account-tile ${a.archived?'archived':''}" data-open-account="${a.id}" role="button" tabindex="0"><div class="account-tile-icon">${svgForAccount(a)}</div><div class="account-tile-main"><b>${acctName(a)}</b><span>${acctTypeLabel(a)}${a.archived?' · 已封存':''}${a.excludeNet?' · 不計入總資產':''}${lowBalanceHit(a)?' · 餘額不足':''}</span></div><strong>${acctMoney(a.balance,a)}</strong><button type="button" class="account-delete-btn account-manage-btn" data-acct-manage="${a.id}" aria-label="管理 ${esc(a.name)}">管理</button></div>`);
  const cardHtml=cards.map(a=>{const used=Math.max(0,Math.abs(a.balance));return `<div class="account-tile ${a.archived?'archived':''} ${selectedCreditCardId===a.id?'active':''}" data-open-credit="${a.id}" role="button" tabindex="0"><div class="account-tile-icon">${svgForAccount(a)}</div><div class="account-tile-main"><b>${esc(a.name)}</b><span>信用卡${a.archived?' · 已封存':''}${a.excludeNet?' · 不計入總資產':''}</span></div><strong>${acctMoney(used,a)}</strong><button type="button" class="account-delete-btn account-manage-btn" data-acct-manage="${a.id}" aria-label="管理 ${esc(a.name)}">管理</button></div>`});
  accountGrid.innerHTML=acctGroupsHTML(cards,cardHtml,normal,normalHtml);
  document.querySelectorAll('[data-open-credit]').forEach(b=>{b.onclick=(e)=>{if(e.target.closest('button'))return;openCreditAccount(b.dataset.openCredit)}});document.querySelectorAll('[data-open-account]').forEach(b=>{b.onclick=(e)=>{if(e.target.closest('button'))return;openAccountDetail(b.dataset.openAccount)}});document.querySelectorAll('[data-open-account]').forEach(b=>{b.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('button')){e.preventDefault();openAccountDetail(b.dataset.openAccount)}}});
  document.querySelectorAll('[data-delete-account]').forEach(b=>b.onclick=async(e)=>{e.preventDefault();e.stopPropagation();await deleteAccount(b.dataset.deleteAccount)});
  if(selectedCreditCardId) renderCreditAccountDetail(); else if(selectedBank) renderBankDetail(); else if(creditAccountDetail) creditAccountDetail.hidden=true;
  renderAccountDetail();
  document.getElementById('view-accounts')?.classList.toggle('has-detail',!!(selectedCreditCardId||selectedBank||selectedAccountId));
}
function openCreditAccount(id){selectedCreditCardId=id;selectedAccountId=null;creditStatementOffset=0;renderAccounts()}
function renderCreditAccountDetail(){
  const el=document.getElementById('creditAccountDetail'), card=acct(selectedCreditCardId);
  if(!el||!card||card.type!=='card'){if(el)el.hidden=true;return}
  const period=cardPeriod(card,new Date(),creditStatementOffset);
  const today=isoDate(new Date());
  const statementTx=state.transactions.filter(t=>String(t.account)===String(card.id)&&t.kind==='expense'&&t.date>=period.start&&t.date<=period.end&&!t.cardPayment).sort((a,b)=>b.date.localeCompare(a.date));
  const unbilled=creditStatementOffset===0?state.transactions.filter(t=>String(t.account)===String(card.id)&&t.kind==='expense'&&t.date>period.end&&t.date<=today&&!t.cardPayment).sort((a,b)=>b.date.localeCompare(a.date)):[];
  const payments=creditStatementPayments(card,period);
  const current=statementTx.reduce((sum,t)=>sum+t.amount,0);
  const paid=payments.reduce((sum,t)=>sum+t.amount,0);
  const due=Math.max(0,current-paid);
  const outstanding=Math.max(0,Math.abs(card.balance));
  const limit=Math.max(0,card.limit||0),available=Math.max(0,limit-outstanding),pct=limit?Math.min(100,outstanding/limit*100):0;
  const sources=state.accounts.filter(a=>a.type!=='card'&&String(a.id)!==String(card.id));
  const status=creditStatementStatus(card,period,paid,current), nextDue=status.date;
  const unbilledTotal=unbilled.reduce((sum,t)=>sum+t.amount,0);
  const txList=(list,empty)=>list.length?list.map(t=>`<button type="button" class="credit-tx-row" data-credit-txid="${t.id}"><span class="credit-tx-main"><b>${esc(t.name)}</b><small>${t.date} · ${esc(t.merchant||'—')}</small></span><span class="credit-tx-side"><b>${money(t.amount)}</b><small>${esc(cat(t.category).name)}</small></span></button>`).join(''):`<div class="credit-empty">${empty}</div>`;
  el.hidden=false;
  el.innerHTML=`
    <div class="detail-close-row"><button type="button" class="secondary" data-close-credit>← 返回帳戶</button></div>
    <div class="credit-detail-head"><div><div class="eyebrow">信用帳戶</div><h3>${esc(card.name)}</h3><div class="hint">帳單週期 ${period.start} ～ ${period.end} · 繳款日 ${card.due||'—'} 日</div></div><div class="credit-period"><button type="button" data-credit-prev aria-label="上一期">‹</button><strong>${period.start} ～ ${period.end}</strong><button type="button" data-credit-next ${creditStatementOffset>=0?'disabled':''} aria-label="下一期">›</button></div></div>
    <div class="credit-cycle-status"><span class="credit-status credit-status-${status.key}">${status.label}</span><b>繳款截止 ${nextDue}</b></div>
    ${creditStatsHTML(creditStats(card,new Date(),creditStatementOffset))}
    <div class="credit-bar-row"><span>可用額度 ${money(available)}</span><span>額度 ${money(limit)} · ${pct.toFixed(0)}%</span></div><div class="credit-bar"><i style="width:${pct}%"></i></div>${creditRewardHTML(card,current,due)}
    <div class="credit-tabs" role="tablist" aria-label="信用卡交易狀態"><button type="button" class="credit-tab ${creditDetailTab==='statement'?'active':''}" data-credit-tab="statement">本期帳單 <b>${statementTx.length}</b></button><button type="button" class="credit-tab ${creditDetailTab==='unbilled'?'active':''}" data-credit-tab="unbilled">未出帳 <b>${unbilled.length}</b></button></div>
    ${creditDetailTab==='statement'?`<div class="credit-bill-summary"><div><span>本期應繳</span><b>${money(current)}</b></div><div><span>已繳</span><b class="green">${money(paid)}</b></div><div><span>尚欠</span><b>${money(due)}</b></div></div><div class="credit-section"><div class="credit-section-head"><h4>繳款記錄</h4><button class="ghost" data-inline-payment="${card.id}" ${sources.length&&due>0?'':'disabled'}>＋ 新增繳款</button></div><div id="creditPaymentForm" class="credit-payment-form" hidden></div>${payments.length?payments.map(p=>`<div class="payment-record"><div><b>${esc(p.name)}</b><div class="meta">${p.date} · ${esc(acct(p.account).name)}</div></div><div class="amount">${money(p.amount)}</div><span class="hint">已完成</span></div>`).join(''):'<div class="credit-empty">本期沒有繳款記錄</div>'}</div><div class="credit-section pane-tx"><div class="credit-section-head"><h4>本期交易明細</h4><span class="hint">${statementTx.length} 筆 · ${money(current)}</span></div><div class="credit-tx-list">${txList(statementTx,'本期尚無交易')}</div></div>`:`<div class="credit-unbilled-card"><div><span>未出帳金額</span><b>${money(unbilledTotal)}</b></div><small>${unbilled.length} 筆 · ${creditStatementOffset===0?'結帳日後新增的消費':'上一期／歷史帳單不顯示未出帳'}</small></div><div class="credit-section pane-tx"><div class="credit-section-head"><h4>未出帳交易</h4><span class="hint">${unbilled.length} 筆</span></div><div class="credit-tx-list">${txList(unbilled,'目前沒有未出帳交易')}</div></div>`}${acctInfoHTML(card)}`;
  const payBtn=el.querySelector('[data-inline-payment]'); if(payBtn)payBtn.onclick=()=>showInlinePayment(card.id,period);
  el.querySelectorAll('[data-credit-tab]').forEach(b=>b.onclick=()=>{creditDetailTab=b.dataset.creditTab;renderCreditAccountDetail()});
  el.querySelectorAll('[data-credit-txid]').forEach(b=>b.onclick=()=>{const t=state.transactions.find(x=>String(x.id)===String(b.dataset.creditTxid));if(t&&!blockLoanTx(t))openTx('expense',t)});
  const prev=el.querySelector('[data-credit-prev]'); if(prev)prev.onclick=()=>{creditStatementOffset--;creditDetailTab='statement';renderCreditAccountDetail()};
  const next=el.querySelector('[data-credit-next]'); if(next)next.onclick=()=>{if(creditStatementOffset<0){creditStatementOffset++;creditDetailTab='statement';renderCreditAccountDetail()}};
}
function showInlinePayment(cardId,periodArg=null){
  const wrap=document.getElementById('creditPaymentForm'); if(!wrap)return;
  const card=acct(cardId), period=periodArg||cardPeriod(card,new Date(),creditStatementOffset), payments=creditStatementPayments(card,period);
  const statementTotal=state.transactions.filter(t=>String(t.account)===String(card.id)&&t.kind==='expense'&&t.date>=period.start&&t.date<=period.end&&!t.cardPayment).reduce((s,t)=>s+t.amount,0);
  const paid=payments.reduce((s,t)=>s+t.amount,0);
  const statementDue=Math.max(0,statementTotal-paid);
  const outstanding=Math.max(0,Math.abs(card.balance));
  const maxAmount=Math.min(statementDue,outstanding);
  const sources=state.accounts.filter(a=>a.type!=='card'&&String(a.id)!==String(cardId));
  wrap.hidden=false;
  if(!sources.length){wrap.innerHTML='<div class="credit-empty">沒有可用的扣款帳戶。</div>';return}
  if(maxAmount<=0){wrap.innerHTML='<div class="credit-empty">本期帳單已經繳清。</div>';return}
  wrap.innerHTML=`<div class="credit-payment-title"><b>繳交 ${period.start} ～ ${period.end} 帳單</b><span>本期尚欠 ${money(maxAmount)}</span></div><div class="credit-payment-grid"><label>繳款金額<input id="inlinePayAmount" type="number" min=1 max="${maxAmount}" value="${maxAmount}"></label><label>扣款帳戶<select id="inlinePaySource">${sources.map(a=>`<option value="${a.id}"${String(a.id)===String(card.payFrom)?' selected':''}>${acctName(a)}（${acctMoney(a.balance,a)}）</option>`).join('')}</select></label></div><div class="credit-payment-actions"><button type="button" class="secondary" id="inlinePayCancel">取消</button><button type="button" class="primary" id="inlinePayConfirm">確認繳款</button></div>`;
  wrap.querySelector('#inlinePayCancel').onclick=()=>{wrap.hidden=true};
  wrap.querySelector('#inlinePayConfirm').onclick=async()=>{
    const source=acct(wrap.querySelector('#inlinePaySource').value);
    const raw=Number(wrap.querySelector('#inlinePayAmount').value||0);
    const amount=Math.min(Math.max(0,raw),maxAmount);
    if(!amount)return alert('請輸入有效繳款金額');
    if(source.balance<amount&&!confirm(`「${source.name}」餘額不足 ${money(amount)}，仍要繼續？`))return;
    source.balance-=amount;
    card.balance+=amount;
    state.transactions.push({id:id(),date:isoDate(new Date()),name:`${card.name} 繳款`,amount,kind:'transfer',category:'',account:source.id,toAccount:card.id,note:'信用卡繳款',cardPayment:true,cardStatementKey:creditStatementKey(card,period)});
    await save();
    render();
    openCreditAccount(card.id);
  };
}

function expenseAmountForCategory(t,categoryId){if(t.kind!=='expense')return 0;if(Array.isArray(t.splits)&&t.splits.length)return t.splits.filter(s=>s.category===categoryId).reduce((a,s)=>a+s.amount,0);return t.category===categoryId?t.amount:0}
function renderBars(){renderAnalysis()}
function renderCardSettings(){} // V26.42: card settings live in 管理帳戶; the always-on panel was removed
function renderBudgets(){renderBudgetPage();renderBudgetOverview()}
// V26.2: recurring transactions. Posting is always a user action (no background auto-posting, so
// several devices can never post the same period twice).
const FREQ_LABEL={day:'天',week:'週',month:'個月',year:'年'};
function normRecurring(r){if(!r)return r;r.kind=r.kind==='income'?'income':'expense';r.freq=FREQ_LABEL[r.freq]?r.freq:'month';r.interval=Math.max(1,Math.floor(Number(r.interval)||1));r.start=r.start||r.next||isoDate(new Date());r.next=r.next||r.start;r.end=r.end&&['never','count','date'].includes(r.end.type)?r.end:{type:'never'};r.seq=Math.max(0,Number(r.seq)||0);r.posted=Math.max(0,Number(r.posted)||0);if(!r.account)r.account=(state.accounts.find(a=>a.type!=='card')||state.accounts[0])?.id||'';return r}
function dim(y,m){return new Date(y,m+1,0).getDate()}
function addPeriod(date,r){const [y,m,d]=date.split('-').map(Number),n=r.interval||1,anchor=Number(String(r.start||date).slice(8,10))||d;if(r.freq==='day'||r.freq==='week'){const t=new Date(y,m-1,d+(r.freq==='week'?7:1)*n);return isoDate(t)}const months=r.freq==='year'?12*n:n,tm=new Date(y,m-1+months,1),yy=tm.getFullYear(),mm=tm.getMonth();return isoDate(new Date(yy,mm,Math.min(anchor,dim(yy,mm))))}
function recurringEnded(r){if(r.ended)return true;if(r.end?.type==='count')return r.seq>=Number(r.end.value||0);if(r.end?.type==='date')return !!r.end.value&&r.next>r.end.value;return false}
function recurringLabel(r){const n=r.seq+1,total=r.end?.type==='count'?`共 ${Number(r.end.value||0)} 期`:r.end?.type==='date'?`至 ${r.end.value}`:'無限期';return `週期 #${n} / ${total}`}
function freqText(r){const every=r.interval>1?`每 ${r.interval} ${FREQ_LABEL[r.freq]}`:`每${FREQ_LABEL[r.freq].replace('個','')}`;if(r.freq==='month')return `${every} ${Number(String(r.start).slice(8,10))} 日`;if(r.freq==='week')return `${every}${WEEKDAYS[new Date(r.start+'T00:00:00').getDay()]}`;return every}
function daysFromToday(date){const [y,m,d]=String(date).split('-').map(Number),t=new Date(),a=new Date(y,m-1,d),b=new Date(t.getFullYear(),t.getMonth(),t.getDate());return Math.round((a-b)/864e5)}
function relDay(date){const n=daysFromToday(date);if(n===0)return '今天';if(n===1)return '明天';if(n===-1)return '昨天';if(n>1)return `${n} 天後`;const a=-n;if(a<7)return `${a} 天前`;if(a<14)return '上星期';if(a<31)return `${Math.floor(a/7)} 星期前`;if(a<62)return '上個月';return `${Math.floor(a/30)} 個月前`}
function advanceRecurring(r){r.seq+=1;r.next=addPeriod(r.next,r);if(recurringEnded(r))r.ended=true}
function recurringTxId(r,seq){return `rec-${r.id}-${seq}`}
function postRecurring(r){normRecurring(r);if(recurringEnded(r))return null;const tid=recurringTxId(r,r.seq+1);if(state.transactions.some(x=>String(x.id)===tid)){r.posted+=1;advanceRecurring(r);return null}const t={id:tid,date:r.next,time:'',name:r.name,amount:Math.abs(Number(r.amount||0)),kind:r.kind,category:r.category||'',account:r.account,merchant:r.merchant||'',note:'',tags:[],recurringId:r.id,recurringSeq:r.seq+1};state.transactions.push(t);adjust(t,1);r.posted+=1;advanceRecurring(r);return t}
function skipRecurring(r){normRecurring(r);if(recurringEnded(r))return;advanceRecurring(r)}
function upcomingList(days=30){const limit=isoDate(new Date(Date.now()+days*864e5));return (state.recurring||[]).map(normRecurring).filter(r=>!recurringEnded(r)&&!r.paused&&r.next<=limit).sort((a,b)=>a.next.localeCompare(b.next))}
function confirmPending(t){if(!t?.pending)return;const unapplied=t.pendingApplied===false;t.pending=false;delete t.pendingApplied;if(unapplied)adjust(t,1)}
function recurringRow(r){const c=cat(r.category),sign=r.kind==='income'?'+':'−',over=daysFromToday(r.next)<0;return `<div class="up-row"><div class="tx-icon">${esc(c.icon)}</div><div class="day-main"><b>${esc(r.name)}</b><small>${recurringLabel(r)}${esc(r.merchant?' · '+r.merchant:'')} · ${acctName(acct(r.account))}</small></div><div class="day-side"><b class="${r.kind==='income'?'income-text':'expense-text'}">${sign}${acctMoney(Math.abs(r.amount),acct(r.account))}</b><small class="${over?'overdue':''}">${relDay(r.next)}</small></div><div class="up-actions"><button type="button" class="primary" data-rec-post="${esc(r.id)}">入帳</button><button type="button" class="ghost" data-rec-skip="${esc(r.id)}">略過</button></div></div>`}
function pendingRow(t){const v=txSigned({...t,pending:false}),label=t.pendingApplied===false?'未計入餘額':'已計入餘額';return `<div class="up-row"><div class="tx-icon">${esc(cat(t.category).icon)}</div><div class="day-main"><b>${esc(t.name)}</b><small>${esc(t.merchant||t.person||'—')} · ${acctName(acct(t.account))} · ${label}</small></div><div class="day-side"><b class="${v<0?'expense-text':v>0?'income-text':''}">${v>0?'+':v<0?'−':''}${money(Math.abs(v||Number(t.amount||0)))}</b><small>${relDay(t.date)}</small></div><div class="up-actions"><button type="button" class="primary" data-pending-confirm="${esc(t.id)}">確認入帳</button><button type="button" class="ghost" data-pending-del="${esc(t.id)}">刪除</button></div></div>`}
function renderUpcoming(){const list=upcomingList(30),sum=list.reduce((s,r)=>s+(r.kind==='income'?1:-1)*(txTWD(Math.abs(r.amount),r.account)??Math.abs(r.amount)),0);const head=document.getElementById('upcomingTotal');if(head)head.textContent=list.length?`${list.length} 筆 · 合計 ${sum<0?'−':'+'}${money(Math.abs(Math.round(sum)))}`:'';upcoming.innerHTML=list.length?list.map(recurringRow).join(''):'<div class="empty">30 天內沒有週期交易</div>'}
function renderPending(){const list=state.transactions.filter(t=>t.pending).sort((a,b)=>String(a.date).localeCompare(String(b.date)));const head=document.getElementById('pendingTotal');if(head)head.textContent=list.length?`${list.length} 筆`:'';pending.innerHTML=list.length?list.map(pendingRow).join(''):'<div class="empty">沒有待完成交易</div>'}
document.addEventListener('click',async e=>{
  const find=v=>(state.recurring||[]).find(r=>String(r.id)===String(v));
  const post=e.target.closest?.('[data-rec-post]');if(post){const r=find(post.dataset.recPost);if(!r)return;const t=postRecurring(r);if(t){await save();render()}return}
  const skip=e.target.closest?.('[data-rec-skip]');if(skip){const r=find(skip.dataset.recSkip);if(!r||!confirm(`略過「${r.name}」${r.next} 這一期？不會建立交易。`))return;skipRecurring(r);await save();render();return}
  const edit=e.target.closest?.('[data-rec-edit]');if(edit){openEntity('recurring',find(edit.dataset.recEdit));return}
  const del=e.target.closest?.('[data-rec-del]');if(del){const r=find(del.dataset.recDel);if(!r||!confirm(`刪除週期交易「${r.name}」？已入帳的交易不會被刪除。`))return;state.recurring=state.recurring.filter(x=>x!==r);await save();render();return}
  const ok=e.target.closest?.('[data-pending-confirm]');if(ok){const t=state.transactions.find(x=>String(x.id)===String(ok.dataset.pendingConfirm));if(!t)return;confirmPending(t);await save();render();return}
  const pd=e.target.closest?.('[data-pending-del]');if(pd){deleteTx(pd.dataset.pendingDel);return}
});
function renderRecurring(){recurringGrid.innerHTML=(state.recurring||[]).map(normRecurring).map(r=>{const ended=recurringEnded(r);return `<div class="entity-card recurring-card ${ended?'ended':''}"><div class="rc-head"><span class="mini-icon">${esc(cat(r.category).icon)}</span><b>${esc(r.name)}</b></div><strong class="${r.kind==='income'?'income-text':'expense-text'}">${r.kind==='income'?'+':'−'}${acctMoney(Math.abs(r.amount),acct(r.account))}</strong><div class="hint">${freqText(r)} · ${acctName(acct(r.account))}${r.auto?' · 自動入帳':''}${r.sub?' · 訂閱':''}${r.paused?' · 已暫停':''}</div><div class="hint">${ended?'已結束':`下一次：${r.next}（${relDay(r.next)}）`} · ${recurringLabel(r)} · 已入帳 ${r.posted} 次</div><div class="rc-actions"><button type="button" class="secondary" data-rec-edit="${esc(r.id)}">編輯</button><button type="button" class="secondary danger-btn" data-rec-del="${esc(r.id)}">刪除</button>${ended?'':`<button type="button" class="secondary" data-rec-sub="${esc(r.id)}">${r.sub?'取消訂閱標記':'標為訂閱'}</button><button type="button" class="secondary" data-rec-pause="${esc(r.id)}">${r.paused?'恢復':'暫停'}</button><button type="button" class="primary" data-rec-post="${esc(r.id)}">入帳本期</button>`}</div></div>`}).join('')||'<div class="empty">尚無週期交易</div>'}function renderProjects(){renderProjectPage()}function renderCategories(){renderCategoryPage()}function renderLoans(){loanGrid.innerHTML=state.loans.map(l=>`<div class="entity-card"><b>${esc(l.person)}</b><strong>${money(l.amount-l.paid)}</strong><div class="hint">總額 ${money(l.amount)} · 已還 ${money(l.paid)}</div></div>`).join('')||'<div class="empty">尚無借還款</div>'}
const MORE_VIEWS=['accounts','loans','budgets','recurring','projects','categories','settings'];
function nav(view){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+view));document.getElementById('mobileMore')?.classList.toggle('active',MORE_VIEWS.includes(view));document.getElementById('moreBg')?.classList.remove('open');setTimeout(()=>{renderBulkBar();if(view==='settings'){renderBackups();renderFxPrefs()}if(view==='analysis')renderAnalysis();if(view==='overview')renderChart()},0);document.querySelectorAll('.nav,.mobile-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));pageTitle.textContent={overview:'概覽',transactions:'交易',accounts:'帳戶',analysis:'分析',budgets:'預算',recurring:'週期',projects:'專案',categories:'分類',loans:'借還款',settings:'設定'}[view]||'概覽'}
function openTx(kind='expense',t=null){editId=t?.id||null;modalTitle.textContent=editId?'編輯交易':t?'複製交易':'新增交易';txForm.reset();txForm.querySelectorAll?.('[data-user-set]').forEach(el=>delete el.dataset.userSet);splitRows.innerHTML='';document.querySelector(`input[name=kind][value="${t?.kind||kind}"]`).checked=true;formDate();if(txForm.elements.time)txForm.elements.time.value=t?(t.time||''):nowTime();if(t){for(let [k,v] of Object.entries(t)){if(k==='splits'||k==='tags'||k==='time')continue;let el=txForm.elements[k];if(el&&typeof v!=='object')el.value=v}if(txForm.elements.tags)txForm.elements.tags.value=Array.isArray(t.tags)?t.tags.join(' '):'';if(txForm.elements.toAmount)txForm.elements.toAmount.value=t.kind==='transfer'&&t.toAmount!==undefined?t.toAmount:'';if(txForm.elements.fee)txForm.elements.fee.value=t.kind==='transfer'&&t.fee?t.fee:'';txForm.elements.pending.checked=!!t.pending;if(Array.isArray(t.splits))t.splits.forEach(addSplitRow)}else{txForm.elements.amount.value='';formAccount.selectedIndex=0}updateKind();entryFillDatalists();updateInstallmentUI();modalBg.classList.add('open');setTimeout(()=>{window.refreshEntryChoices?.();updateSplitSummary()},0)}
function formDate(){txForm.elements.date.value=editId?(state.transactions.find(t=>t.id===editId)?.date||selectedDate):selectedDate}function updateKind(){const isT=document.querySelector('input[name=kind]:checked').value==='transfer';document.querySelectorAll('.transfer-only').forEach(el=>el.style.display=isT?'grid':'none');updateTransferFx()}
window.editTx=id=>openTx('expense',state.transactions.find(t=>String(t.id)===String(id)));
function closeModals(){modalBg.classList.remove('open');entityBg.classList.remove('open')}
async function submitTx(e){e.preventDefault();let f=new FormData(txForm),kind=f.get('kind'),amount=Number(f.get('amount')||0);if(!amount||amount<0){alert('請輸入有效金額');return}const rows=[...splitRows.querySelectorAll('.split-row')];let splits=rows.map(r=>({category:r.querySelector('[data-split-category]').value,amount:Number(r.querySelector('[data-split-amount]').value||0)})).filter(x=>x.amount>0);if(splits.length){const total=splits.reduce((s,x)=>s+x.amount,0);if(Math.abs(total-amount)>0){alert(`拆帳金額未平衡\n交易金額：${money(amount)}\n拆帳合計：${money(total)}\n差額：${money(Math.abs(amount-total))}`);return}}let oldEdit=editId?state.transactions.find(x=>x.id===editId):null;let t={...(oldEdit||{}),id:editId||id(),time:String(f.get('time')||''),tags:parseTags(f.get('tags')),date:f.get('date'),name:f.get('name'),amount,kind,category:f.get('category'),account:f.get('account'),toAccount:f.get('toAccount'),project:f.get('project'),merchant:f.get('merchant'),person:String(f.get('person')||'').trim(),note:f.get('note'),pending:!!f.get('pending'),splits:splits.length?splits:undefined};if(t.pending)t.pendingApplied=oldEdit?(oldEdit.pending?oldEdit.pendingApplied:false):false;else delete t.pendingApplied;if(!oldEdit?.imported){if(kind==='transfer'){const tf=transferFields(amount,t.account,t.toAccount,f.get('toAmount'),f.get('fee'));if(tf.error){alert(tf.error);return}for(const [k,v] of Object.entries(tf)){if(v===undefined)delete t[k];else t[k]=v}}else{for(const k of ['toAccount','toAmount','toBalanceEffect','toCurrency','fee'])delete t[k];if(!t.imported)delete t.balanceEffect}}if(oldEdit?.imported){t.imported=true;t.recordType=oldEdit.recordType;t.balanceEffect=(oldEdit.recordType?Number(oldEdit.balanceEffect??0):(kind==='expense'?-amount:kind==='income'?amount:0));if(kind==='transfer')t.toBalanceEffect=Number(oldEdit.toBalanceEffect??oldEdit.toAmount??amount);}if(editId){let old=state.transactions.find(x=>x.id===editId);if(old)adjust(old,-1);state.transactions=state.transactions.map(x=>x.id===editId?t:x)}else if(f.get('instOn')&&kind==='expense'){const plan=installmentPlan(t,f.get('instCount'));if(plan?.error){alert(plan.error);return}if(plan){for(const x of plan.list){state.transactions.push(x);adjust(x,1)}await save();window.state=state;window.mozeState=state;closeModals();render();window.refreshEntryChoices?.();return}state.transactions.push(t)}else{state.transactions.push(t);if(prefs().jumpToTxDate&&t.date){selectedDate=t.date;const [yy,mm]=t.date.split('-').map(Number);calendarMonth=new Date(yy,mm-1,1)}}adjust(t,1);await save();window.state=state;window.mozeState=state;closeModals();render();window.refreshEntryChoices?.()}
// V26.2: pending transactions created from V26.2 on carry pendingApplied:false and do not touch balances
// until confirmed. Older pending ones (no flag) were already applied and keep counting.
function isUnappliedPending(t){return !!t?.pending&&t.pendingApplied===false}
function adjust(t,sign){if(isUnappliedPending(t))return;if(t.kind==='transfer'){let src=acct(t.account);src.balance+=sign*Number(t.balanceEffect??(-t.amount));let dst=acct(t.toAccount);dst.balance+=sign*Number(t.toBalanceEffect??(t.toAmount??t.amount));return}if(t.imported&&t.balanceEffect!==undefined){acct(t.account).balance+=sign*Number(t.balanceEffect||0);return}if(t.kind==='expense'){let a=acct(t.account);a.balance-=sign*t.amount}else if(t.kind==='income'){let a=acct(t.account);a.balance+=sign*t.amount}else if(t.kind==='balance_adjustment'){acct(t.account).balance+=sign*t.amount}}
function splitCategories(){return state.categories.filter(c=>c.kind==='expense').map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}
function updateSplitSummary(){const amount=Number(txForm.elements.amount.value||0);const rows=[...splitRows.querySelectorAll('.split-row')];const total=rows.reduce((s,r)=>s+Number(r.querySelector('[data-split-amount]')?.value||0),0);const box=document.getElementById('splitSummary');if(!box)return;const diff=amount-total;box.innerHTML=rows.length?`<span>拆帳 ${rows.length} 筆 · 已分配 ${money(total)}</span><b class="${diff===0?'split-ok':'split-warn'}">${diff===0?'✓ 已平衡':'差額 '+money(Math.abs(diff))}</b>`:'<span>未拆帳</span><b>$0</b>';}
function addSplitRow(data={}){let d=document.createElement('div');d.className='split-row';d.innerHTML=`<select data-split-category>${splitCategories()}</select><input data-split-amount type="number" min="0" step="1" placeholder="金額" value="${data.amount||''}"><button type="button" class="icon" data-remove-split>×</button>`;splitRows.appendChild(d);if(data.category)d.querySelector('[data-split-category]').value=data.category;d.querySelector('[data-split-amount]').addEventListener('input',updateSplitSummary);d.querySelector('[data-split-category]').addEventListener('change',updateSplitSummary);d.querySelector('[data-remove-split]').onclick=()=>{d.remove();updateSplitSummary()};updateSplitSummary();}
const entityBgEl=document.getElementById('entityBg'),entityFormEl=document.getElementById('entityForm'),entityTitleEl=document.getElementById('entityTitle'),entityFieldsEl=document.getElementById('entityFields'),cardSettingsEl=document.getElementById('cardSettings');
function openEntity(type){let fields={account:[['name','帳戶名稱'],['balance','初始餘額']],budget:[['limit','預算金額']],project:[['name','專案名稱'],['budget','預算']],category:[['name','分類名稱'],['icon','Icon']],recurring:[['name','名稱'],['amount','金額'],['next','下次日期']],loan:[['person','對象'],['amount','金額']]};entityTitleEl.textContent='新增'+({account:'帳戶',budget:'預算',project:'專案',category:'分類',recurring:'週期交易',loan:'借還款'}[type]);if(type==='account'){entityFieldsEl.innerHTML=`${acctImageFieldHTML({})}<div class="entity-field"><label>帳戶名稱<input name="name" required></label></div><div class="entity-field"><label>類型<select name="accountType"><option value="bank">銀行</option><option value="cash">現金</option><option value="ewallet">電子支付</option><option value="broker">證券戶</option><option value="foreign">外幣</option><option value="card">信用卡</option></select></label></div><div class="entity-field"><label>初始餘額／目前欠款<input name="balance" type="number" value="0" required></label></div>${acctBankFieldHTML({},false)}<div id="newCardFields" style="display:none">${acctCardFieldsHTML({limit:50000},true)}</div>`;entityFieldsEl.querySelector('[name=accountType]').onchange=e=>{document.getElementById('newCardFields').style.display=e.target.value==='card'?'block':'none'}}else entityFieldsEl.innerHTML=(fields[type]||[]).map(([n,l])=>`<div class="entity-field"><label>${l}<input name="${n}" type="${n==='amount'||n==='balance'||n==='budget'||n==='limit'?'number':n==='next'?'date':'text'}" required></label></div>`).join('');entityFormEl.dataset.type=type;entityBgEl.classList.add('open')}
async function submitEntity(e){e.preventDefault();let f=new FormData(entityFormEl),type=entityFormEl.dataset.type;if(type==='account'){let at=f.get('accountType')||'bank',bal=Number(f.get('balance')||0);state.accounts.push({id:id(),name:f.get('name'),type:at,balance:at==='card'?-Math.abs(bal):bal,limit:at==='card'?Number(f.get('limit')||0):undefined,statement:at==='card'?Number(f.get('statement')||15):undefined,due:at==='card'?Number(f.get('due')||5):undefined})};if(type==='category')state.categories.push({id:id(),name:f.get('name'),icon:f.get('icon')||'•',kind:'expense'});if(type==='project')state.projects.push({id:id(),name:f.get('name'),budget:Number(f.get('budget')||0)});if(type==='budget')state.budgets.push({id:id(),category:state.categories[0]?.id,limit:Number(f.get('limit')||0)});if(type==='recurring')state.recurring.push({id:id(),name:f.get('name'),amount:Number(f.get('amount')||0),next:f.get('next'),category:state.categories[0]?.id});if(type==='loan')state.loans.push({id:id(),person:f.get('person'),amount:Number(f.get('amount')||0),paid:0});await save();closeModals();render()}


/* V25.8 — full loan page + CSV receivable/payable integration */
function loanDirection(l){return l&&l.direction==='payable'?'payable':'receivable'}
function loanOutstanding(l){return Math.max(0,Number(l?.amount||0)-Number(l?.paid||0))}
function loanStatus(l){return l?.status==='stopped'?'stopped':loanOutstanding(l)<=0?'completed':'active'}
function loanLabel(dir){return dir==='payable'?'應付':'應收'}
function loanActionLabel(dir){return dir==='payable'?'還款':'收款'}
function loanEnsureModel(l){
  if(!l)return l;
  l.direction=loanDirection(l); l.amount=Math.max(0,Number(l.amount||0)); l.paid=Math.max(0,Math.min(l.amount,Number(l.paid||0)));
  l.payments=Array.isArray(l.payments)?l.payments:[];
  l.status=loanStatus(l);
  return l;
}
function loanNetSummary(){
  const ls=(state.loans||[]).map(loanEnsureModel);
  const receivable=ls.filter(l=>loanDirection(l)==='receivable'&&loanStatus(l)!=='stopped').reduce((s,l)=>s+loanOutstanding(l),0);
  const payable=ls.filter(l=>loanDirection(l)==='payable'&&loanStatus(l)!=='stopped').reduce((s,l)=>s+loanOutstanding(l),0);
  return {receivable,payable,net:receivable-payable,active:ls.filter(l=>loanStatus(l)==='active').length,completed:ls.filter(l=>loanStatus(l)==='completed').length};
}
// V25.19: loan editing. Every loan / loanPayment transaction carries loanId; deleting reverses the
// exact account effect the transaction applied (imported rows keep balanceEffect incl. fee/discount).
function loanTxs(loan){return (state.transactions||[]).filter(t=>String(t.loanId)===String(loan.id))}
function loanTxEffect(t){if(t.imported&&t.balanceEffect!==undefined)return Number(t.balanceEffect)||0;const a=Math.abs(Number(t.amount||0));if(t.kind==='loan')return t.loanAction==='lend'?-a:a;if(t.kind==='loanPayment')return t.loanDirection==='receivable'?a:-a;return 0}
function loanPaymentTx(loan,p){const list=loanTxs(loan).filter(t=>t.kind==='loanPayment');return list.find(t=>t.paymentId!==undefined&&String(t.paymentId)===String(p.id))||list.find(t=>t.paymentId===undefined&&t.date===p.date&&Number(t.amount)===Number(p.amount)&&String(t.account)===String(p.account))||null}
function reverseLoanTx(t){const a=state.accounts.find(x=>String(x.id)===String(t.account));if(a)a.balance=Math.round((Number(a.balance||0)-loanTxEffect(t))*100)/100;state.transactions=state.transactions.filter(x=>x!==t)}
function refreshLoanStatus(loan){if(loan.status!=='stopped')loan.status=loanOutstanding(loan)<=0?'completed':'active'}
function removeLoan(loan){const txs=loanTxs(loan);txs.forEach(reverseLoanTx);state.loans=state.loans.filter(l=>l!==loan);return txs.length}
function removeLoanPayment(loan,p){if(loan.historicalOnly)return {removedLoan:true,txCount:removeLoan(loan)};const t=loanPaymentTx(loan,p);if(t)reverseLoanTx(t);loan.payments=loan.payments.filter(x=>x!==p);loan.paid=Math.max(0,Number(loan.paid||0)-Number(p.amount||0));refreshLoanStatus(loan);return {removedLoan:false,txFound:!!t}}
function loanEffectText(txs){const by=new Map();for(const t of txs){const a=acct(t.account);const k=a.id?acctName(a):'未知帳戶';by.set(k,(by.get(k)||0)-loanTxEffect(t))}return [...by].filter(([,v])=>Math.abs(v)>=0.005).map(([k,v])=>`${k} ${v>0?'+':''}${money(v)}`).join('、')||'無'}
function loanFilterMatch(l,filter){const st=loanStatus(l);if(filter==='completed')return st==='completed'||st==='stopped';if(filter==='receivable')return loanDirection(l)==='receivable'&&st==='active';if(filter==='payable')return loanDirection(l)==='payable'&&st==='active';return true}
function renderLoans(){
  const cards=document.getElementById('loanSummaryCards'), grid=document.getElementById('loanGrid'), detail=document.getElementById('loanDetailPanel'), count=document.getElementById('loanCount');
  if(!grid)return;
  (state.loans||[]).forEach(loanEnsureModel);
  const sum=loanNetSummary();
  if(cards)cards.innerHTML=`<article class="loan-summary-card receivable"><small>應收款項</small><strong>${money(sum.receivable)}</strong><span>尚未收回的借款／代付款</span></article><article class="loan-summary-card payable"><small>應付款項</small><strong>${money(sum.payable)}</strong><span>尚未償還的借款／負債</span></article><article class="loan-summary-card net"><small>借還款淨額</small><strong>${money(sum.net)}</strong><span>${sum.active} 筆進行中 · ${sum.completed} 筆已完成</span></article>`;
  const filter=window.__mozeLoanFilter||'all';
  document.querySelectorAll('[data-loan-filter]').forEach(b=>b.classList.toggle('active',b.dataset.loanFilter===filter));
  const ls=(state.loans||[]).filter(l=>loanFilterMatch(l,filter));
  if(count)count.textContent=`${ls.length} 筆`;
  const groups=new Map();
  ls.forEach(l=>{const p=l.person||'未指定對象';if(!groups.has(p))groups.set(p,[]);groups.get(p).push(l)});
  if(!ls.length){grid.innerHTML='<div class="panel empty">目前沒有符合條件的借還款</div>'}
  else{
    grid.innerHTML=[...groups.entries()].map(([person,list])=>{
      const personNet=list.reduce((s,l)=>s+(loanDirection(l)==='receivable'?1:-1)*loanOutstanding(l),0);
      const active=list.filter(l=>loanStatus(l)==='active').length;
      return `<div class="loan-person-group"><div class="loan-person-head"><div class="loan-person-title"><b>${esc(person)}</b><span>${active} 筆進行中 · ${list.length-active} 筆已完成</span></div><div class="loan-person-total"><b class="${personNet>=0?'income-text':'expense-text'}">${personNet>=0?'+':''}${money(personNet)}</b><span>未結餘額</span></div></div>${list.map(l=>{const dir=loanDirection(l),outstanding=loanOutstanding(l),pct=l.amount?Math.min(100,(l.paid/l.amount)*100):100;const done=loanStatus(l)!=='active';return `<div class="loan-row" data-loan-id="${l.id}"><span class="loan-direction ${dir}">${loanLabel(dir)}</span><div class="loan-main"><b>${esc(l.name||((dir==='receivable'?'借出':'借入')+' · '+person))}</b><span>${l.date||'未設定日期'}${esc(l.account?' · '+acct(l.account).name:'')}${l.dueDate?' · 到期 '+l.dueDate:''}</span></div><div class="loan-progress"><div class="loan-progress-track"><i style="width:${pct}%"></i></div><div class="loan-progress-label"><span>已 ${money(l.paid)}</span><span>${pct.toFixed(0)}%</span></div></div><div class="loan-row-amount"><b class="${done?'':'income-text'}">${money(outstanding)}</b><span>${done?'已完成':'剩餘'}</span></div><button type="button" class="loan-action" data-loan-action="${l.id}" ${done?'disabled':''}>${loanActionLabel(dir)}</button></div>`}).join('')}</div>`;
    }).join('');
  }
  renderLoanDetail();
  // Keep the overview compact but useful.
  renderLoanTracking();
}
function renderLoanDetail(){
  const panel=document.getElementById('loanDetailPanel'); if(!panel)return;
  const id=window.__mozeSelectedLoanId; const loan=(state.loans||[]).find(l=>String(l.id)===String(id));
  if(!loan){panel.hidden=true;panel.innerHTML='';return;}
  loanEnsureModel(loan); panel.hidden=false;
  const dir=loanDirection(loan), out=loanOutstanding(loan), payAccounts=(state.accounts||[]).filter(a=>a.type!=='card');
  const defaultAccount=loan.account||payAccounts[0]?.id||'';
  panel.innerHTML=`<div class="loan-detail-head"><div class="loan-detail-title"><div class="loan-detail-icon">${dir==='payable'?'↙':'↗'}</div><div><h3>${esc(loan.person||'未指定對象')}</h3><p>${loanLabel(dir)} · ${esc(loan.name||'借還款記錄')}${loan.date?' · '+loan.date:''}${loan.dueDate?' · 到期 '+loan.dueDate:''}</p></div></div><button type="button" class="secondary" data-loan-close>關閉</button></div><div class="loan-detail-summary"><div class="loan-detail-box"><span>原始金額</span><b>${money(loan.amount)}</b></div><div class="loan-detail-box"><span>已${dir==='payable'?'還':'收'}</span><b>${money(loan.paid)}</b></div><div class="loan-detail-box"><span>剩餘${dir==='payable'?'應還':'應收'}</span><b class="${out?'':'income-text'}">${money(out)}</b></div></div>${out?`<div class="loan-payment-area"><h4>${loanActionLabel(dir)}</h4><div class="loan-payment-form"><label>金額<div class="loan-payment-amount"><input id="loanPaymentAmount" type="number" min="1" max="${out}" step="1" value="${out}"><button type="button" data-loan-full>全額</button></div></label><label>實際帳戶<select id="loanPaymentAccount">${payAccounts.map(a=>`<option value="${a.id}" ${String(a.id)===String(defaultAccount)?'selected':''}>${acctName(a)} · ${acctMoney(a.balance,a)}</option>`).join('')}</select></label><label>日期<input id="loanPaymentDate" type="date" value="${selectedDate}"></label><label>備註<input id="loanPaymentNote" type="text" placeholder="可留空"></label></div><div class="loan-payment-actions"><button type="button" class="primary" data-loan-confirm="${loan.id}">${loanActionLabel(dir)}</button></div></div>`:'<div class="loan-payment-area"><div class="empty">這筆款項已完成</div></div>'}<div class="loan-history"><div class="loan-history-head"><h4 style="margin:0">${loanActionLabel(dir)}記錄</h4><span class="hint" style="margin:0">${loan.payments.length} 筆</span></div><div class="loan-history-list">${loan.payments.length?loan.payments.slice().reverse().map(p=>`<div class="loan-history-row"><span>${p.date||''}</span><div>${esc(p.account?acct(p.account).name:'未指定帳戶')}${p.note?`<div class="hint" style="margin:2px 0 0">${esc(p.note)}</div>`:''}</div><b>${money(p.amount)}</b><button type="button" class="loan-pay-del" data-loan-pay-del="${esc(p.id)}" aria-label="刪除這筆記錄" title="刪除這筆記錄">刪除</button></div>`).join(''):'<div class="empty">尚無收還款記錄</div>'}</div></div>${String(window.__mozeLoanEditId)===String(loan.id)?`<div class="loan-edit-form"><h4>編輯借還款</h4><div class="loan-payment-form"><label>對象<input id="loanEditPerson" value="${esc(loan.person||'')}"></label><label>名稱<input id="loanEditName" value="${esc(loan.name||'')}"></label><label>到期日<input id="loanEditDue" type="date" value="${esc(loan.dueDate||'')}"></label><label>備註<input id="loanEditNote" value="${esc(loan.note||'')}"></label></div><p class="hint">金額、帳戶與日期不能直接修改，以免帳戶餘額不一致；請刪除後重新建立。</p><div class="loan-payment-actions"><button type="button" class="secondary" data-loan-edit-cancel>取消</button><button type="button" class="primary" data-loan-edit-save="${loan.id}">儲存</button></div></div>`:''}<div class="loan-detail-actions"><span class="hint" style="margin:0">停止追蹤後會移到「已完成」，不會刪除歷史資料。刪除會一併刪除相關交易並還原帳戶餘額。</span><div class="loan-detail-buttons"><button type="button" class="secondary" data-loan-edit="${loan.id}">編輯</button>${loanStatus(loan)==='stopped'?`<button type="button" class="secondary" data-loan-resume="${loan.id}">恢復追蹤</button>`:`<button type="button" class="secondary loan-stop" data-loan-stop="${loan.id}" ${loanStatus(loan)==='active'?'':'disabled'}>停止追蹤</button>`}<button type="button" class="secondary danger-btn" data-loan-delete="${loan.id}">刪除</button></div></div>`;
}
function selectLoan(id){window.__mozeSelectedLoanId=id;renderLoans();document.getElementById('loanDetailPanel')?.scrollIntoView({behavior:'smooth',block:'nearest'})}
function openEntity(type,editing=null){entityFormEl.dataset.editId=editing?.id||'';
  const fields={account:[['name','帳戶名稱'],['balance','初始餘額']],budget:[['limit','預算金額']],project:[['name','專案名稱'],['budget','預算']],category:[['name','分類名稱'],['icon','Icon']],recurring:[['name','名稱'],['amount','金額'],['next','下次日期']],loan:[['person','對象'],['amount','金額']]};
  entityTitleEl.textContent='新增'+({account:'帳戶',budget:'預算',project:'專案',category:'分類',recurring:'週期交易',loan:'借還款'}[type]);
  if(type==='account'){
    entityFieldsEl.innerHTML=`${acctImageFieldHTML({})}<div class="entity-field"><label>帳戶名稱<input name="name" required></label></div><div class="entity-field"><label>類型<select name="accountType"><option value="bank">銀行</option><option value="cash">現金</option><option value="ewallet">電子支付</option><option value="broker">證券戶</option><option value="foreign">外幣</option><option value="card">信用卡</option></select></label></div><div class="form-grid"><label>初始餘額／目前欠款<input name="balance" type="number" step="any" value="0" required></label>${acctCurrencyField('TWD',false)}</div><div class="form-grid form-grid-1"><label>備註<input name="anote" maxlength="100" placeholder="可留空"></label></div>${acctNewOptionsHTML()}${acctBankFieldHTML({},false)}<div id="newCardFields" style="display:none">${acctCardFieldsHTML({limit:50000},true)}</div>`;
    entityFieldsEl.querySelector('[name=accountType]').onchange=e=>{document.getElementById('newCardFields').style.display=e.target.value==='card'?'block':'none';const bf=entityFieldsEl.querySelector('[data-acct-bank-field]');if(bf)bf.hidden=!(e.target.value==='card'||e.target.value==='foreign')};
  }else if(type==='loan'){
    entityFieldsEl.innerHTML=`<div class="entity-help">借給別人選「應收」；向別人借錢選「應付」。建立後會同步調整實際帳戶餘額，但不會算成一般支出／收入。</div><div class="seg"><label><input type="radio" name="direction" value="receivable" checked>應收・借出</label><label><input type="radio" name="direction" value="payable">應付・借入</label></div><div class="form-grid"><label>對象<input name="person" required placeholder="例如：小明"></label><label>金額<input name="amount" type="number" min="1" step="1" required></label><label>實際帳戶<select name="account" required>${state.accounts.filter(a=>a.type!=='card').map(a=>`<option value="${a.id}">${acctName(a)} · ${acctMoney(a.balance,a)}</option>`).join('')}</select></label><label>日期<input name="date" type="date" value="${selectedDate}" required></label><label>到期日<input name="dueDate" type="date"></label><label>名稱<input name="loanName" placeholder="例如：借朋友生活費"></label></div><div class="entity-field"><label>備註<input name="note" placeholder="可留空"></label></div>`;
    entityFieldsEl.querySelectorAll('input[name=direction]').forEach(r=>r.onchange=()=>{});
  }else if(type==='accountEdit'){
    entityTitleEl.textContent='管理帳戶';entityFieldsEl.innerHTML=acctEditFormHTML(editing);
  }else if(type==='accountAdjust'){
    entityTitleEl.textContent='調整餘額';entityFieldsEl.innerHTML=acctAdjustFormHTML(editing);
  }else if(type==='project'){
    if(editing)entityTitleEl.textContent='編輯專案';entityFieldsEl.innerHTML=projFormHTML(editing);
  }else if(type==='category'){
    entityTitleEl.textContent=editing&&!editing.__new?'編輯分類':editing?.parentId?'新增子分類':'新增分類';entityFieldsEl.innerHTML=catFormHTML(editing);catFormBind(entityFieldsEl);
  }else if(type==='categoryDelete'){
    entityTitleEl.textContent='刪除分類';entityFieldsEl.innerHTML=catDeleteFormHTML(editing);
  }else if(type==='budget'){
    if(editing)entityTitleEl.textContent='編輯預算';entityFieldsEl.innerHTML=budgetFormHTML(editing);budgetFormSync(entityFieldsEl);entityFieldsEl.querySelectorAll('input[name=bscope]').forEach(r=>r.onchange=()=>budgetFormSync(entityFieldsEl));
  }else if(type==='recurring'){
    const r=editing?normRecurring({...editing}):{kind:'expense',freq:'month',interval:1,start:selectedDate,end:{type:'never'}};if(editing)entityTitleEl.textContent='編輯週期交易';
    const opt=(v,l,cur)=>`<option value="${v}" ${String(v)===String(cur)?'selected':''}>${l}</option>`;
    entityFieldsEl.innerHTML=`<div class="seg"><label><input type="radio" name="rkind" value="expense" ${r.kind!=='income'?'checked':''}>支出</label><label><input type="radio" name="rkind" value="income" ${r.kind==='income'?'checked':''}>收入</label></div><div class="form-grid"><label>名稱<input name="name" required value="${esc(r.name||'')}" placeholder="例如：房租"></label><label>金額<input name="amount" type="number" min="0" step="any" required value="${r.amount??''}"></label><label>分類<select name="category">${state.categories.map(c=>opt(c.id,`${esc(c.icon)} ${esc(c.name)}`,r.category)).join('')}</select></label><label>帳戶<select name="account">${state.accounts.map(a=>opt(a.id,acctName(a),r.account)).join('')}</select></label><label>商家<input name="merchant" value="${esc(r.merchant||'')}" placeholder="可留空"></label><label>開始日期<input name="start" type="date" required value="${esc(r.start||selectedDate)}"></label><label>頻率<select name="freq">${opt('day','天',r.freq)}${opt('week','週',r.freq)}${opt('month','月',r.freq)}${opt('year','年',r.freq)}</select></label><label>每隔<input name="interval" type="number" min="1" step="1" value="${r.interval||1}"></label><label>結束<select name="endType">${opt('never','無限期',r.end.type)}${opt('count','共幾期',r.end.type)}${opt('date','到某天',r.end.type)}</select></label><label>結束值<input name="endValue" value="${esc(r.end.value??'')}" placeholder="期數或 YYYY-MM-DD"></label><label class="check rc-auto"><input type="checkbox" name="rauto" ${r.auto?'checked':''}>到期自動入帳（開啟 App 時補記已到期的各期）</label></div>${editing?`<p class="hint">下一次：${esc(r.next)}。修改開始日期會把下一次重設為開始日期。</p>`:''}`;
  }else{
    entityFieldsEl.innerHTML=(fields[type]||[]).map(([n,l])=>`<div class="entity-field"><label>${l}<input name="${n}" type="${n==='amount'||n==='balance'||n==='budget'||n==='limit'?'number':n==='next'?'date':'text'} required></label></div>`).join('');
  }
  entityFormEl.dataset.type=type;entityBgEl.classList.add('open');
}
async function submitEntity(e){
  e.preventDefault();let f=new FormData(entityFormEl),type=entityFormEl.dataset.type;
  if(type==='account'){let at=f.get('accountType')||'bank',bal=Number(f.get('balance')||0),cur=String(f.get('acur')||'TWD').trim().toUpperCase(),nm=String(f.get('name')||'').trim();if(!nm){alert('請輸入帳戶名稱');return}if(!/^[A-Z]{3}$/.test(cur)){alert('幣別請輸入 3 個英文字母，例如 TWD、USD');return}if(state.accounts.some(a=>a.name===nm&&acctCur(a)===cur)){alert(`已經有「${nm}（${cur}）」`);return}state.accounts.push({id:id(),name:nm,currency:cur,note:String(f.get('anote')||'').trim()||undefined,type:at,balance:at==='card'?-Math.abs(bal):bal,...(at==='card'?acctCardSettingsFromForm(f):(at==='foreign'||cur!=='TWD')?acctBankFromForm(f):{}),...acctOptionsFromForm(f,at),...acctImageFromForm(f)});}
  if(type==='category'){const editId=entityFormEl.dataset.editId,old=editId?state.categories.find(c=>String(c.id)===String(editId)):null,res=catFromForm(f,old);if(res.error){alert(res.error);return}if(old){if(!old.parentId&&old.kind!==res.category.kind)catChildren(old).forEach(k=>k.kind=res.category.kind);state.categories=state.categories.map(c=>c===old?res.category:c)}else{res.category.order=catSiblings(res.category).length;state.categories.push(res.category)}}
  if(type==='categoryDelete'){const editId=entityFormEl.dataset.editId,c=state.categories.find(x=>String(x.id)===String(editId)),to=f.get('ctarget');if(!c||!to){alert('請選擇要改用的分類');return}catReassign(c.id,to);state.categories=state.categories.filter(x=>x!==c)}
  if(type==='accountEdit'){const editId=entityFormEl.dataset.editId,old=state.accounts.find(a=>String(a.id)===String(editId));if(!old)return;const res=acctFromEditForm(f,old);if(res.error){alert(res.error);return}state.accounts=state.accounts.map(a=>a===old?res.account:a);if(res.account.type!=='card'&&String(selectedCreditCardId)===String(old.id))selectedCreditCardId=null}
  if(type==='accountAdjust'){const editId=entityFormEl.dataset.editId,a=state.accounts.find(x=>String(x.id)===String(editId));if(!a)return;const v=Number(f.get('abalance'));if(!Number.isFinite(v)){alert('請輸入實際餘額');return}if(!acctAdjustTo(a,v,f.get('adate'),String(f.get('anote')||'').trim())){alert('餘額沒有變動');return}}
  if(type==='project'){const editId=entityFormEl.dataset.editId,old=editId?state.projects.find(p=>String(p.id)===String(editId)):null,res=projFromForm(f,old);if(res.error){alert(res.error);return}if(old)state.projects=state.projects.map(p=>p===old?res.project:p);else state.projects.push(res.project)}
  if(type==='budget'){const editId=entityFormEl.dataset.editId,old=editId?state.budgets.find(b=>String(b.id)===String(editId)):null,res=budgetFromForm(f,old);if(res.error){alert(res.error);return}if(old)state.budgets=state.budgets.map(b=>b===old?res.budget:b);else state.budgets.push(res.budget)}
  if(type==='recurring'){const editId=entityFormEl.dataset.editId,old=editId?state.recurring.find(r=>String(r.id)===String(editId)):null,start=f.get('start')||selectedDate,endType=f.get('endType')||'never',endRaw=String(f.get('endValue')||'').trim();if(endType==='count'&&!(Number(endRaw)>=1)){alert('請輸入結束期數（至少 1）');return}if(endType==='date'&&!/^\d{4}-\d{2}-\d{2}$/.test(endRaw)){alert('請以 YYYY-MM-DD 輸入結束日期');return}const r={...(old||{id:id(),seq:0,posted:0}),auto:!!f.get('rauto'),name:f.get('name'),amount:Math.abs(Number(f.get('amount')||0)),kind:f.get('rkind')==='income'?'income':'expense',category:f.get('category')||'',account:f.get('account')||'',merchant:f.get('merchant')||'',freq:f.get('freq')||'month',interval:Math.max(1,Number(f.get('interval')||1)),start,end:endType==='never'?{type:'never'}:{type:endType,value:endType==='count'?Math.floor(Number(endRaw)):endRaw}};if(!old||old.start!==start)r.next=start;r.ended=false;if(recurringEnded(r))r.ended=true;if(old)state.recurring=state.recurring.map(x=>x===old?r:x);else state.recurring.push(r)}
  if(type==='loan'){
    const direction=f.get('direction')==='payable'?'payable':'receivable',amount=Math.abs(Number(f.get('amount')||0)),account=acct(f.get('account'));
    if(!amount||!account||!account.id){alert('請輸入有效的金額與帳戶');return}
    const loanId=id(),date=f.get('date')||selectedDate,person=f.get('person')||'未指定對象';
    const loan={id:loanId,person,direction,amount,paid:0,account:account.id,date,dueDate:f.get('dueDate')||'',name:f.get('loanName')||((direction==='receivable'?'借出給 ':'借入自 ')+person),note:f.get('note')||'',payments:[],status:'active'};
    state.loans.push(loan);
    account.balance += direction==='receivable' ? -amount : amount;
    state.transactions.push({id:id(),date,name:loan.name,amount,kind:'loan',loanId,direction,loanAction:direction==='receivable'?'lend':'borrow',account:account.id,note:loan.note,person,category:'',loanRecord:true});
  }
  await save();closeModals();render();if(type==='loan'){window.__mozeLoanFilter='all';window.__mozeSelectedLoanId=type==='loan'?state.loans[state.loans.length-1].id:null;renderLoans();}
}
function txEffect(t){
  if(!t)return 0;
  if(t.kind==='expense')return -Math.abs(Number(t.amount||0));
  if(t.kind==='income')return Math.abs(Number(t.amount||0));
  if(t.kind==='transfer')return 0;
  if(t.kind==='loan')return t.loanAction==='lend'?-Math.abs(Number(t.amount||0)):Math.abs(Number(t.amount||0));
  if(t.kind==='loanPayment')return t.loanDirection==='receivable'?Math.abs(Number(t.amount||0)):-Math.abs(Number(t.amount||0));
  return 0;
}
function txTypeLabel(t){return t.kind==='expense'?'支出':t.kind==='income'?'收入':t.kind==='transfer'?'轉帳':t.kind==='loanPayment'?'收還款':'借還款'}
function txRow(t){let c=cat(t.category),effect=txEffect(t);return `<div class="row"><div class="row-left"><div class="mini-icon">${esc(c.icon)}</div><div><b>${esc(t.name)}</b><div class="hint">${esc(t.merchant||t.person||'')} · ${esc(acct(t.account).name)}</div></div></div><div class="amount ${effect<0?'expense-text':effect>0?'income-text':''}">${effect>0?'+':effect<0?'−':''}${money(Math.abs(effect||t.amount||0))}</div></div>`}
function openDetail(id){let t=state.transactions.find(x=>String(x.id)===String(id));if(!t)return;window.detailId=t.id;let c=cat(t.category),project=t.project?(state.projects.find(p=>String(p.id)===String(t.project))?.name||'—'):'無專案',effect=txEffect(t);detailTitle.textContent=t.name;detailSubtitle.textContent=t.date;detailGrid.innerHTML=`<div class="detail-box"><small>金額</small><b class="${effect<0?'expense-text':effect>0?'income-text':''}">${effect>0?'+':effect<0?'−':''}${money(Math.abs(effect||t.amount||0))}</b></div><div class="detail-box"><small>類型</small><b>${txTypeLabel(t)}</b></div><div class="detail-box"><small>分類</small><b>${esc(c.icon)} ${esc(c.name)}</b></div><div class="detail-box"><small>帳戶</small><b>${esc(acct(t.account).name)}</b></div><div class="detail-box"><small>專案</small><b>${project}</b></div><div class="detail-box"><small>商家／對象</small><b>${esc(t.merchant||t.person||'—')}</b></div><div class="detail-box"><small>時間</small><b>${esc(t.time||'—')}</b></div>${t.installment?`<div class="detail-box"><small>分期</small><b>${installmentLabel(t)}</b></div>`:''}${t.kind==='transfer'?`<div class="detail-box"><small>轉入</small><b>${acctName(acct(t.toAccount))} ${acctMoney(Number(t.toAmount??t.amount),acct(t.toAccount))}</b></div>${t.fee?`<div class="detail-box"><small>手續費</small><b>${money(t.fee)}</b></div>`:''}`:''}<div class="detail-box"><small>標籤</small><b>${tagsHtml(t)||'—'}</b></div><div class="detail-box detail-wide"><small>備註</small><b>${esc(t.note||'—')}</b></div>`;detailBg.classList.add('open')}
function renderTransactions(){txFillAdvanced();const f=txFilterState(),all=txSearchRun(f),ts=all.slice(0,txLimit);let summary=txSummaryHTML(txSearchSummary(all),ts.length,f);let groups={};ts.forEach(t=>(groups[t.date]??=[]).push(t));let body=Object.entries(groups).map(([date,list])=>{let dayOut=list.filter(t=>t.kind==='expense').reduce((s,t)=>s+t.amount,0),dayIn=list.filter(t=>t.kind==='income').reduce((s,t)=>s+t.amount,0);return `<div class="tx-group"><div class="tx-group-head"><b>${date}</b><span>${dayOut?'支出 '+money(dayOut):''}${dayIn?' · 收入 '+money(dayIn):''}</span></div>${list.map(t=>{let amount=txEffect(t);return `<div class="tx-entry ${bulkMode&&bulkSel.has(String(t.id))?'bulk-selected':''}" data-txid="${t.id}"><div class="tx-icon">${bulkMode?`<input type="checkbox" class="bulk-check" aria-label="選取" ${bulkSel.has(String(t.id))?'checked':''}>`:esc(cat(t.category).icon)}</div><div><div class="tx-name">${esc(t.name)}</div><div class="tx-meta">${esc(t.merchant||t.person||'—')} · ${esc(acct(t.account).name)}${esc(t.project?' · '+(state.projects.find(p=>String(p.id)===String(t.project))?.name||''):'')}${txExtra(t)}</div></div><div class="tx-type">${txTypeLabel(t)}</div><div class="tx-actions"><b class="tx-amount ${amount<0?'expense-text':amount>0?'income-text':''}">${amount>0?'+':amount<0?'−':''}${money(Math.abs(amount||t.amount))}</b></div></div>`}).join('')}</div>`}).join('')||'<div class="panel empty">找不到符合條件的交易</div>';txTable.innerHTML=summary+`<div class="tx-groups">${body}</div>`+(all.length>ts.length?`<div class="tx-more"><button type="button" class="secondary" id="txMore">再顯示 ${Math.min(300,all.length-ts.length).toLocaleString()} 筆（還有 ${(all.length-ts.length).toLocaleString()} 筆）</button></div>`:'');document.querySelectorAll('.tx-entry').forEach(row=>row.onclick=()=>{if(!bulkMode)return openDetail(row.dataset.txid);const k=String(row.dataset.txid);if(bulkSel.has(k))bulkSel.delete(k);else bulkSel.add(k);row.classList.toggle('bulk-selected',bulkSel.has(k));const cb=row.querySelector('.bulk-check');if(cb)cb.checked=bulkSel.has(k);renderBulkBar()});renderBulkBar();document.getElementById('txMore')?.addEventListener('click',()=>{txLimit+=300;renderTransactions()});document.getElementById('txClearFilters')?.addEventListener('click',()=>{txClearAdvanced();txLimit=300;renderTransactions()});document.getElementById('txExport')?.addEventListener('click',downloadTxExport)}
function renderAccountDetail(){const el=document.getElementById('accountDetail'),a=selectedAccountId?acct(selectedAccountId):null;if(!el||!a||!a.id||a.type==='card'){if(el)el.hidden=true;return}const ts=state.transactions.filter(t=>String(t.account)===String(a.id)||String(t.toAccount)===String(a.id)).sort((x,y)=>y.date.localeCompare(x.date));const income=ts.filter(t=>t.kind==='income'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0);const expense=ts.filter(t=>t.kind==='expense'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0);const transferIn=ts.filter(t=>t.kind==='transfer'&&String(t.toAccount)===String(a.id)).reduce((s,t)=>s+t.amount,0);const transferOut=ts.filter(t=>t.kind==='transfer'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0);el.hidden=false;el.innerHTML=`<div class="account-detail-head"><div class="account-detail-title"><div class="account-detail-icon">${svgForAccount(a)}</div><div><h3>${acctName(a)}</h3><div class="hint">${acctTypeLabel(a)} · 帳戶明細</div></div></div><button type="button" class="secondary" data-close-account-detail>關閉</button></div><div class="account-detail-summary"><div class="account-summary-box"><span>目前餘額</span><b>${acctMoney(a.balance,a)}</b></div><div class="account-summary-box"><span>收入</span><b class="income-text">${money(income+transferIn+ts.filter(t=>t.kind==='loan'&&t.loanAction==='borrow'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0)+ts.filter(t=>t.kind==='loanPayment'&&t.loanDirection==='receivable'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0))}</b></div><div class="account-summary-box"><span>支出</span><b class="expense-text">${money(expense+transferOut+ts.filter(t=>t.kind==='loan'&&t.loanAction==='lend'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0)+ts.filter(t=>t.kind==='loanPayment'&&t.loanDirection==='payable'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0))}</b></div></div>${acctInfoHTML(a)}<div class="pane-tx"><div class="panel-head" style="margin:8px 0 10px"><h3 style="margin:0">相關交易</h3><span class="hint">${ts.length} 筆</span></div><div class="account-detail-list">${ts.length?ts.map(t=>{const c=cat(t.category),effect=txEffect(t),cls=effect<0?'expense-text':effect>0?'income-text':'';return `<div class="account-detail-row"><span class="account-detail-date">${t.date}</span><div class="mini-icon">${esc(c.icon)}</div><div><b>${esc(t.name)}</b><div class="tx-meta">${esc(t.merchant||t.person||t.note||'—')}${t.kind==='transfer'?' · 轉帳':''}</div></div><div class="amount ${cls}">${effect>0?'+':effect<0?'−':''}${money(Math.abs(effect||t.amount||0))}</div></div>`}).join(''):'<div class="empty">目前沒有相關交易</div>'}</div></div>`;el.querySelector('[data-close-account-detail]')?.addEventListener('click',()=>{selectedAccountId=null;el.hidden=true;renderAccounts()})}

