bind(quickAdd,'click',()=>openTx());bind(mobileAdd,'click',()=>openTx());bind(newTx,'click',()=>openTx());bind(modalClose,'click',closeModals);bind(detailClose,'click',()=>detailBg.classList.remove('open'));bind(detailEdit,'click',()=>{let t=state.transactions.find(x=>String(x.id)===String(window.detailId));if(blockLoanTx(t))return;detailBg.classList.remove('open');if(t)openTx('expense',t)});bind(detailDelete,'click',()=>deleteTx(window.detailId));bind(modalCancel,'click',closeModals);bind(entityClose,'click',closeModals);bind(entityCancel,'click',closeModals);bind(txForm,'submit',submitTx);bind(entityFormEl,'submit',submitEntity);bind(addSplit,'click',()=>addSplitRow());document.querySelectorAll('input[name=kind]').forEach(x=>x.onchange=updateKind);[txSearch,txType,txCategory,txAccount,...['txRange','txFrom','txTo','txMin','txMax','txTag','txProject','txStatus','txSort'].map(i=>document.getElementById(i))].forEach(x=>{bind(x,'input',()=>{txLimit=300;renderTransactions()});bind(x,'change',()=>{txLimit=300;renderTransactions()})});bind(newAccount,'click',()=>openEntity('account'));bind(newBudget,'click',()=>openEntity('budget'));bind(newProject,'click',()=>openEntity('project'));bind(newCategory,'click',()=>openEntity('category'));bind(newRecurring,'click',()=>openEntity('recurring'));bind(newLoan,'click',()=>openEntity('loan'));document.addEventListener('click',e=>{let b=e.target.closest('[data-save-one-card]');if(b){e.preventDefault();let row=b.closest('[data-card-setting]'),a=acct(b.dataset.saveOneCard);if(row&&a){a.limit=Math.max(0,Number(row.querySelector('[data-field=limit]').value||0));a.statement=Math.min(31,Math.max(1,Number(row.querySelector('[data-field=statement]').value||15)));a.due=Math.min(31,Math.max(1,Number(row.querySelector('[data-field=due]').value||5)));save().then(()=>{render();openCreditAccount(a.id)}).catch(err=>alert('儲存失敗：'+err.message))}}});bind(todayBtn,'click',()=>{const now=new Date();selectedDate=now.toISOString().slice(0,10);calendarMonth=new Date(now.getFullYear(),now.getMonth(),1);renderCalendar();renderDaily();renderMetrics();renderChart();renderCards()});bind(prevPeriod,'click',()=>{calendarMonth.setMonth(calendarMonth.getMonth()-1);selectedDate=monthKey(calendarMonth)+'-01';render()});bind(nextPeriod,'click',()=>{calendarMonth.setMonth(calendarMonth.getMonth()+1);selectedDate=monthKey(calendarMonth)+'-01';render()});bind(calendarPrev,'click',()=>{calendarMonth.setMonth(calendarMonth.getMonth()-1);selectedDate=monthKey(calendarMonth)+'-01';renderCalendar();renderDaily();renderMetrics();renderChart();renderCards()});bind(calendarNext,'click',()=>{calendarMonth.setMonth(calendarMonth.getMonth()+1);selectedDate=monthKey(calendarMonth)+'-01';renderCalendar();renderDaily();renderMetrics();renderChart();renderCards()});bind(resetAll,'click',async()=>{const cloud=!!window.MozeSync?.isLoggedIn?.();if(!confirm(`確定清除所有資料？\n\n會刪除本機所有帳戶、交易、分類、專案、預算、週期交易與借還款，只保留預設分類與兩個空帳戶。${cloud?'\n\n⚠️ 目前已登入雲端同步：雲端上的資料也會一併刪除。':''}\n\n清除前會自動下載 JSON 備份。`))return;if(cloud&&!confirm('再次確認：雲端資料也會刪除，無法復原（只能用剛下載的 JSON 備份匯回）。確定清除？'))return;let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download=`moze-before-reset-${isoDate(new Date())}.json`;a.click();state=clone(seed);await save();render()});bind(exportJson,'click',()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='moze-backup.json';a.click()});bind(importJson,'click',()=>importFile?.click());bind(importFile,'change',async e=>{let f=e.target.files[0];if(!f)return;try{state=JSON.parse(await f.text());await save();render()}catch{alert('JSON 格式錯誤')}});
